create table customers (customer_id text primary key, customer_name text, first_quote date, last_quote date, quote_count int not null default 0);
create table parts (part_id bigint generated always as identity primary key, id text generated always as (part_id::text) stored, part_no text not null, drawing_no text not null default '', description text not null default '', embedding pgcontext.vector, unique(part_no,drawing_no,description));
create table quotes (quote_no text primary key, id text generated always as (quote_no) stored, part_id bigint references parts(part_id), customer_id text references customers(customer_id), quote_date date, date_stamp date, rev text, rfq_no text, buyer_name text, salesperson text, status text not null default 'open' check(status in ('won','open')), won_date date, to_quote text references quotes(quote_no), comment text, comment_embedding pgcontext.vector, assembly_no text, item_no text, letter_date date, has_breaks boolean not null default false);
create table quote_qty_breaks (break_id bigint generated always as identity primary key, quote_no text not null references quotes(quote_no), quote_letter text, del_seq int, quantity numeric(14,2), unit_price numeric(14,6), unit_cost numeric(14,6), extended_price numeric(16,4), markup numeric(10,4), newsellpri numeric(14,6), is_placeholder boolean not null default false);
create table quote_letters (quote_letter text primary key, letter_date date, customer_id text references customers(customer_id), material text, quote_count int not null default 0);
create table quote_letter_lines (quote_letter text not null references quote_letters(quote_letter), quote_no text not null references quotes(quote_no), material text, letter_date date, primary key(quote_letter,quote_no));
create table estimates (estimate_id bigint generated always as identity primary key, customer_id text references customers(customer_id), request_id text unique);
create table estimate_lines (line_id bigint generated always as identity primary key, estimate_id bigint not null references estimates(estimate_id), quote_no text references quotes(quote_no));
